go test -count=1 -overlay $P/overlay.json -run '^TestProbe' ./claude > $P/gt.log 2>&1 || { if grep -q '^--- FAIL' $P/gt.log; then awk '/^--- FAIL/{p=1} p' $P/gt.log | grep -vE '^(ok[[:space:]]|PASS$|FAIL$)' | head -200; else tail -60 $P/gt.log; fi; node $P/firstdiff.mjs $P/gt.log; exit 1; }
rm -f claude/launch-args_probe_test.go
[ "$E" = 0 ] || { echo "== vet or gofmt failed (see above); every step between it and here passed"; exit 1; }
echo '== imports'; I=$(go list -e -overlay $P/overlay.json -f '{{join .Imports " "}}' ./claude) || exit 1; for i in $I; do case $i in bufio|bytes|context|encoding/json|errors|fmt|io|os|os/exec|path/filepath|strconv|strings|sync|syscall|time) ;; *) echo "imports: package claude imports $i (allowed: bufio, bytes, context, encoding/json, errors, fmt, io, os, os/exec, path/filepath, strconv, strings, sync, syscall, time)"; exit 1;; esac; done
echo '== clock'; C=$(gofmt -l -r 'time.Now -> time.Time' claude/args.go 2>&1)$(gofmt -l -r 'time.Since -> time.Time' claude/args.go 2>&1); [ -z "$C" ] || { echo "clock: claude/args.go reads time.Now or time.Since (the clock is the now argument)"; exit 1; }
echo '== full'; go test -count=1 -overlay $P/full.json ./... > $P/gt.log 2>&1 || { if grep -q '^--- FAIL' $P/gt.log; then awk '/^--- FAIL/{p=1} p' $P/gt.log | grep -vE '^(ok[[:space:]]|PASS$|FAIL$)' | head -200; else tail -60 $P/gt.log; fi; node $P/firstdiff.mjs $P/gt.log; exit 1; }
echo '== frozen'; git diff --quiet HEAD -- contour.yaml morph-map.json docs decks tests/fixtures go.mod go.sum internal vendor stream runner queue session eventlog telegram || { echo "changed outside the targets: $(git diff --name-only HEAD -- contour.yaml morph-map.json docs decks tests/fixtures go.mod go.sum internal vendor stream runner queue session eventlog telegram | tr "\n" " ")"; exit 1; }
X=$(git ls-files --others --exclude-standard | grep -vxF -e claude/args.go || true); [ -z "$X" ] || { echo "files left in the tree: $X"; exit 1; }
) > $L 2>&1; rc=$?; cat $L; exit $rc

